def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Final round: defection is strictly dominant.
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c

    # If the opponent is clearly defective, defect.
    if op_c == 0:
        return 'D'
    if op_d * 3 > n:
        return 'D'

    # Evidence of forgiveness: opponent's action one round after we defected.
    d_c = 0
    d_d = 0
    for i in range(n - 1):
        if me[i] == 'D':
            if op[i + 1] == 'C':
                d_c += 1
            else:
                d_d += 1

    last_me = me[-1]
    last_op = op[-1]

    # Use a stricter cooperation threshold for exploitation.
    very_cooperative = op_c * 4 >= n * 3

    # If we just defected and the opponent just cooperated, do not press
    # immediately unless they have already repeatedly proved forgiving.
    if last_me == 'D' and last_op == 'C':
        if very_cooperative and d_c >= d_d + 2:
            return 'D'
        return 'C'

    # Opponent just defected: tit-for-tat with a one-round forgiveness loop.
    if last_op == 'D':
        run = 1
        for i in range(n - 2, -1, -1):
            if op[i] == 'D':
                run += 1
            else:
                break

        # If we also defected, this was likely mutual punishment; try peace once.
        if last_me == 'D' and run == 1:
            return 'C'

        # Otherwise punish persistent defection.
        return 'D'

    # Mutual cooperation: preserve it, but late exploit confirmed pushovers.
    if last_me == 'C' and last_op == 'C':
        if very_cooperative:
            if d_c >= d_d + 2 or (n >= 70 and d_c > d_d):
                return 'D'
        return 'C'

    return 'C'
